documents.text:
query Board {
  discover {
    board {
      board {
        tickets {
          id
          title
          state
          lane
          claimedBy
          note
          by
        }
      }
    }
  }
}

query Charge($input: ChargeInput!) {
  discover {
    board {
      charge(input: $input) {
        subtotal
        shipping
      }
    }
  }
}

mutation ClaimWork($input: ClaimWorkInput!) {
  dispatch {
    claimWork(input: $input) {
      output {
        problem {
          code
          message
        }
        ticket {
          id
          title
          report
          state
          lane
        }
        lane
        instructions
        tools
        events
        deadline
      }
    }
  }
}

mutation FileTicket($input: FileTicketInput!) {
  dispatch {
    fileTicket(input: $input) {
      output {
        id
        title
        state
        lane
      }
    }
  }
}
